Hund h1 = new Hund();
h1.name = "Bello";
h1.alter = 3;
h1.istStubenrein = true;

Hund h2 = new Hund();
h2.name = "Cara";
h2.alter = 16;
h2.istStubenrein = false;

h1.kannAlleineBleiben();
h2.kannAlleineBleiben();

class Hund {
   String name;
   Integer alter;
   Boolean istStubenrein;

   void kannAlleineBleiben() {
      if (istStubenrein == true) {
         println(name + " kann alleine bleiben.");
      } else {
         println(name + " sollte nicht alleine bleiben.");
      }
   }
}
